{
  "id": 50,
  "knowledge": "Battery Efficiency Classification",
  "description": "A categorical framework for evaluating and classifying the battery efficiency of gaming devices based on their Battery Efficiency Ratio (BER).",
  "definition": "A classification system that segments wireless gaming devices into four efficiency categories: 'Excellent Efficiency' (BER > 7.5) indicating marathon gaming capability, 'Good Efficiency' (BER between 5.0 and 7.5) for extended gaming sessions, 'Average Efficiency' (BER between 2.5 and 4.9) suitable for regular gameplay, and 'Poor Efficiency' (BER < 2.5) requiring frequent recharging, providing standardized comparison metrics across different gaming peripherals."
}

{
  "id": 53,
  "knowledge": "Global Efficiency Percentile (GEP)",
  "description": "Ranks a device\u2019s Battery Efficiency Ratio (BER) relative to all other wireless gaming devices.",
  "definition": "GEP = \\text{PERCENT\\_RANK}()_{BER} \\times 100, where PERCENT\\_RANK() is computed over all devices sorted by BER; 0\\% corresponds to the lowest BER and 100\\% to the highest."
}

{
  "id": 13,
  "knowledge": "Extended Battery Life Device",
  "description": "Identifies devices with exceptionally efficient battery performance for extended gaming sessions.",
  "definition": "A device with BER > 7.5, BattLifeH > 30, QChgFlag = true, and PwrIdleMw < 100, enabling marathon gaming sessions with minimal charging interruptions."
}

{
  "id": 35,
  "knowledge": "Wireless Performance Efficiency (WPE)",
  "description": "Evaluates the efficiency of wireless performance relative to battery consumption for untethered gaming devices.",
  "definition": "WPE = WPR \\times \\sqrt{\\frac{BER}{5}} \\times \\left(1 - \\frac{WlLatVar}{3}\\right) \\times 2"
}

{
  "id": 8,
  "knowledge": "Wireless Performance Rating (WPR)",
  "description": "Rates the quality of wireless connectivity based on range, latency, and interference handling.",
  "definition": "WPR = \\frac{WlRangeM}{10} \\times \\left(1 - \\frac{WlLatVar}{5}\\right) \\times \\left(1 + \\frac{WlChanHop}{2}\\right) \\times \\frac{WlSignal + 100}{100}, \\text{ where higher values indicate more reliable wireless performance with better range and stability.}"
}

